# Bám sách: trang 44–45 + đáp án + Mini dictionary unit 20. Không chép nguyên văn.
theory = (
 H("A", "Metaphorical uses of phrasal verbs to suggest conflict or violence", "Phrasal verb dùng theo nghĩa bóng để gợi xung đột, bạo lực")
 + P("These verbs are very typical of newspapers: their metaphorical meanings are good for word play.", "Các động từ này rất hay gặp trên báo: nghĩa bóng của chúng thuận lợi cho việc chơi chữ.")
 + T([
    ("<b>wipe out</b>", "The government promised to make poverty disappear completely.", "Chính phủ hứa xóa sổ hoàn toàn đói nghèo."),
    ("<b>fight off</b>", "A minister is resisting demands that she resign.", "Một bộ trưởng đang chống đỡ những lời kêu gọi bà từ chức."),
    ("<b>drag</b> sb <b>into</b>", "Some newspapers are trying to involve the prime minister in a scandal.", "Một số báo đang cố lôi thủ tướng vào vụ bê bối."),
    ("<b>strike back at</b>", "He wrote an article to attack the critics who had attacked him (literally, <i>strike</i> = hit).", "Ông viết bài báo để đáp trả những người đã chỉ trích mình (nghĩa đen của <i>strike</i> là đánh)."),
 ])
 + H("B", "Talking about conflict and violence", "Nói về xung đột và bạo lực")
 + P("Five short conversations.", "Năm đoạn hội thoại ngắn.")
 + T([
    ("<b>smash up</b>", "Emma couldn’t buy a ticket: the office was closed and vandals had destroyed the machine on the platform.", "Emma không mua được vé: phòng vé đóng cửa, còn máy bán vé trên sân ga bị kẻ phá hoại đập nát."),
    ("<b>fly at</b> / <b>round on</b>", "Albert complained; the boss suddenly spoke to him very angrily, then turned and shouted at the others.", "Albert phàn nàn; ông chủ bất ngờ quát anh, rồi quay sang mắng những người khác."),
    ("<b>flare up</b> / <b>fly into</b> a rage", "Albert had never seen him become so angry so suddenly.", "Albert chưa từng thấy ông ấy nổi giận đột ngột như thế."),
    ("<b>bust-up</b> / <b>push</b> sb <b>around</b>", "(informal) It was their biggest angry argument with him, but they won’t let him order them about rudely.", "(thân mật) Đó là trận cãi lớn nhất với ông ấy, nhưng họ sẽ không để ông ấy sai khiến thô lỗ."),
    ("<b>push over</b> / <b>come at</b> / <b>fight off</b>", "A man made Alex fall, approached him from behind to take his bag; Alex used force to make him go away.", "Một người xô Alex ngã, lao tới từ phía sau để giật túi; Alex chống trả khiến hắn bỏ đi."),
    ("<b>set</b> sth <b>on</b> sb / <b>knock out</b> / <b>break up</b>", "Neighbours fought over stolen plants: one made his dog attack the other; someone was almost made unconscious; police had to stop the fight.", "Hàng xóm đánh nhau vì cây bị trộm: một người xua chó cắn người kia; có người suýt bị đánh bất tỉnh; cảnh sát phải can."),
    ("<b>bump off</b>", "(informal) In a film, the man who had been killing everyone was caught.", "(thân mật) Trong phim, kẻ đã giết hết mọi người cuối cùng bị bắt."),
 ])
 + H("C", "Particles in phrasal verbs connected with conflict and violence", "Tiểu từ trong phrasal verb về xung đột, bạo lực")
 + table(["Particle", "Meaning it adds (from the book)"], ["Tiểu từ", "Ý thêm vào (theo sách)"], [
    ("<b>up</b>", "", "extreme or complete: <b>smash up</b>, <b>flare up</b>", "cực độ, hoàn toàn"),
    ("<b>at</b>", "", "direction of the violent action: <b>come at</b>, <b>fly at</b>", "hướng của hành động bạo lực"),
    ("<b>off</b>", "", "remove: <b>bump off</b>, <b>fight off</b>", "loại bỏ"),
    ("<b>out</b>", "", "remove completely: <b>wipe out</b>", "loại bỏ hoàn toàn"),
 ])
 + NOTE("The book advises thinking about what the particle adds so you can learn these verbs in groups. <b>Exercise 20.2</b>: <b>push</b> sb <b>around</b> = boss them; <b>push over</b> = literally push them to the floor.",
        "Sách khuyên nghĩ xem tiểu từ thêm ý gì để học theo nhóm. <b>Bài 20.2</b>: <b>push</b> sb <b>around</b> = sai khiến; <b>push over</b> = xô ngã xuống sàn theo nghĩa đen.")
)
